insert into public.groups (id, name, subtitle, tagline, timezone) values
  ('family', 'The Shoreline', 'Family Mastermind', 'A family mastermind, rooted and growing together', 'America/Chicago');
insert into public.group_settings (group_id, branding, verse, credit, rules, rules_version, location_default, meeting_rule, training_rule, agenda_template, notification_options) values
  ('family', '{"dedication":"In loving memory of Marie & Shane","nextLabel":"Next gathering","enterLabel":"Cast off","colors":{"primary":"#1F4D3A","accent":"#E0A458","background":"#F4EFE2","text":"#1F4D3A","surface":"#FFFDF6","muted":"#4F6358","rule":"#E3DCC9","secondary":"#5B8C7A","good":"#2E8B57","goodBg":"#DDF0E4"},"logoText":"M·S","logoSvg":"brand/shoreline-logo.svg"}'::jsonb, '{"short":"Even there your hand will guide me.","full":"Even there your hand will guide me, your right hand will hold me fast.","ref":"Psalm 139:10"}'::jsonb, '{"label":"Built by TPG","url":"https://PLACEHOLDER-tpg-website"}'::jsonb, '["What''s said in the room stays in the room. Ask before sharing someone''s story.","Show up. If you can''t make it, tell Mark before the day of.","Check in before the meeting starts so we can read wins and challenges ahead of time.","Hot seat prep is in 24 hours before the meeting.","Phones face down during the meeting, except to take notes.","Advice is a gift. Say thank you, then decide for yourself.","Everyone leaves with one commitment, and we follow up on it."]'::jsonb, 1, '{"type":"zoom","label":"Zoom","url":"https://zoom.us/j/0000000000?pwd=PLACEHOLDER","address":null}'::jsonb, '{"nth":3,"weekday":3,"start":"19:30","durationMinutes":60,"titleTemplate":"{month} Shoreline"}'::jsonb, null, '[{"time":5,"item":"Opening prayer and wins of the month","owner":"m1"},{"time":10,"item":"Commitment check-in, round the table","owner":"all"},{"time":25,"item":"Hot seat: {hotSeatName}","owner":"{hotSeat}"},{"time":15,"item":"Choose the 2027 book list","owner":"m10"},{"time":5,"item":"New commitments and close","owner":"m1"}]'::jsonb, '{"oneHourReminder":true}'::jsonb);
insert into public.group_invites (group_id, code_hash, code_hint) values ('family', public.hash_invite_code('family', 'FAMILY2026'), '26');
insert into public.members (id, group_id, name, role, bio, focus, can_help_with, working_genius, sort_order) values
  ('m1', 'family', 'Mark Ellison', 'admin', 'Retired CPA. Runs the family investment fund and the estate planning.', 'Getting the family trust update signed before Christmas.', array['Taxes and retirement accounts','Reading a contract','Estate planning basics']::text[], '{"geniuses":["D","G"],"competencies":["W","T"],"frustrations":["I","E"]}'::jsonb, 1),
  ('m2', 'family', 'Linda Ellison', 'member', 'Retired teacher. Coordinates the church outreach team.', 'Filling 25 volunteer spots for the Thanksgiving give-back.', array['Organizing volunteers','Editing a letter or resume','Planning a family event']::text[], '{"geniuses":["G","E"],"competencies":["D","T"],"frustrations":["W","I"]}'::jsonb, 2),
  ('m3', 'family', 'Jake Ellison', 'member', 'Line cook testing a food truck with Saturday pop-ups.', 'Proving the truck can do $500 a Saturday before signing a lease.', array['Cooking for a crowd','Social media photos','Lifting and hauling']::text[], '{"geniuses":["I","G"],"competencies":["W","E"],"frustrations":["D","T"]}'::jsonb, 3),
  ('m4', 'family', 'Sarah Ruiz', 'member', 'Runs a bookkeeping practice for small businesses, mostly contractors.', 'Moving every client to the new January pricing.', array['QuickBooks setup','Budgeting','Small business taxes']::text[], '{"geniuses":["D","E"],"competencies":["T","I"],"frustrations":["W","G"]}'::jsonb, 4),
  ('m5', 'family', 'Daniel Ruiz', 'member', 'Electrician. Owns two rental units and a vacant lot.', 'Deciding whether to fix or sell the Maple duplex.', array['Electrical and home repair','Rental property questions','Finding contractors']::text[], null, 5),
  ('m6', 'family', 'Emily Ellison', 'member', 'Data analyst at a regional insurance company, moving toward product management.', 'Landing a product manager interview by January.', array['Spreadsheets and data','Interview prep','Online courses that are worth it']::text[], '{"geniuses":["W","D"],"competencies":["I","T"],"frustrations":["G","E"]}'::jsonb, 6),
  ('m7', 'family', 'Ben Ellison', 'member', 'High school senior. Mows lawns in the neighborhood on weekends.', 'Pricing out a lawn care business for spring.', array['Yard work','Phone and computer help','Moving furniture']::text[], null, 7),
  ('m8', 'family', 'Grace Ellison', 'member', 'College sophomore studying nursing. Works part time at the campus clinic.', 'Building a $1,000 emergency fund by May.', array['Health questions (non-emergency)','Babysitting','Study tips']::text[], null, 8),
  ('m9', 'family', 'Tom Whitaker', 'member', 'Financial analyst at a credit union. Learning the family fund books from Mark.', 'Writing a Q3 fund summary everyone can follow.', array['Investing basics','Loans and credit','Excel models']::text[], '{"geniuses":["I","D"],"competencies":["T","E"],"frustrations":["W","G"]}'::jsonb, 9),
  ('m10', 'family', 'Hannah Whitaker', 'member', 'Nurse practitioner. Organizes the family service days.', 'Getting every cousin to the Nov 21 food bank shift.', array['Health questions','Planning service projects','Picking good books']::text[], '{"geniuses":["E","W"],"competencies":["G","T"],"frustrations":["I","D"]}'::jsonb, 10);
insert into public.meetings (id, group_id, starts_at, duration_minutes, title, location, agenda, hot_seat_member_id, hot_seat_prep, action_plan, source_key) values
  ('f-2026-08', 'family', '2026-08-09T15:00:00-05:00', 60, 'August Shoreline', null, '[{"time":5,"item":"Opening prayer and wins of the month","owner":"m1"},{"time":10,"item":"Commitment check-in, round the table","owner":"all"},{"time":25,"item":"Hot seat: Jake''s food truck permit plan","owner":"m3"},{"time":15,"item":"Book discussion: The E-Myth Revisited, ch. 1-4","owner":"m2"},{"time":5,"item":"New commitments and close","owner":"m1"}]'::jsonb, 'm3', '{"problem":"Should I lease a used truck now or run a pop-up tent at the farmers market for a season first?","context":"I''ve saved $14k. A used truck lease is $1,900/month plus a $6k build-out. The farmers market spot is $85 a Saturday.","whatTried":"Priced three trucks, talked to two owners at the county fair, wrote a rough menu of six items.","winLooksLike":"A clear yes or no on the truck, and a test I can run before Thanksgiving.","submittedAt":"2026-08-07T19:30:00-05:00"}'::jsonb, null, 'rule:2026-08'),
  ('f-2026-09', 'family', '2026-09-13T15:00:00-05:00', 60, 'September Shoreline', null, '[{"time":5,"item":"Opening prayer and wins of the month","owner":"m1"},{"time":10,"item":"Commitment check-in, round the table","owner":"all"},{"time":25,"item":"Hot seat: Sarah''s bookkeeping side business pricing","owner":"m4"},{"time":15,"item":"Family investment fund: Q3 review","owner":"m9"},{"time":5,"item":"New commitments and close","owner":"m1"}]'::jsonb, 'm4', '{"problem":"I have 6 clients at $150/month. Do I raise prices for new clients only, or for everyone in January?","context":"Every client takes 5-7 hours a month. Local bookkeepers charge $250-400. I''m scared of losing the two church clients.","whatTried":"Looked up three competitors and tracked my hours for August.","winLooksLike":"A price I can say out loud without flinching, and a script for telling current clients.","submittedAt":"2026-09-11T21:15:00-05:00"}'::jsonb, '{"adviceTaken":["Raise new clients to $250 starting now","Give current clients 60 days notice for January","Offer the church clients a nonprofit rate"],"nextStep":"Email all current clients the new January pricing.","deadline":"2026-10-31","goalId":"g-m4-1","savedAt":"2026-09-13T18:50:00-05:00"}'::jsonb, 'rule:2026-09'),
  ('f-2026-10', 'family', '2026-10-11T15:00:00-05:00', 60, 'October Shoreline', null, '[{"time":5,"item":"Opening prayer and wins of the month","owner":"m1"},{"time":10,"item":"Commitment check-in, round the table","owner":"all"},{"time":25,"item":"Hot seat: Daniel''s rental property decision","owner":"m5"},{"time":15,"item":"Planning the Thanksgiving give-back project","owner":"m10"},{"time":5,"item":"New commitments and close","owner":"m1"}]'::jsonb, 'm5', '{"problem":"The duplex on Maple needs $18k in repairs. Do we fix and rent it, or sell as-is and put the money into the second lot?","context":"Bought it in 2019 for $142k. Comparable rentals get $1,150 per side. Roof and one furnace are the big items.","whatTried":"Got one rough quote and asked a realtor for an as-is number ($205k).","winLooksLike":"A decision we both feel good about and a deadline to make it by.","submittedAt":"2026-10-09T20:40:00-05:00"}'::jsonb, '{"adviceTaken":["Get a second contractor bid before deciding","Run the numbers at 8% vacancy, not zero","Ask the realtor what a fixed-up unit would sell for","Decide by the December meeting"],"nextStep":"Get two contractor bids on the Maple duplex repairs.","deadline":"2026-11-07","goalId":"g-m5-1","savedAt":"2026-10-11T19:20:00-05:00"}'::jsonb, 'rule:2026-10'),
  ('f-2026-11', 'family', '2026-11-08T15:00:00-06:00', 60, 'November Shoreline', null, '[{"time":5,"item":"Opening prayer and wins of the month","owner":"m1"},{"time":10,"item":"Commitment check-in, round the table","owner":"all"},{"time":25,"item":"Hot seat: Emily''s career move","owner":"m6"},{"time":15,"item":"2027 family goals: first draft","owner":"m2"},{"time":5,"item":"New commitments and close","owner":"m1"}]'::jsonb, 'm6', null, null, 'rule:2026-11'),
  ('f-2026-12', 'family', '2026-12-13T15:00:00-06:00', 60, 'December Shoreline', '{"type":"inperson","label":"In person","url":null,"address":"Mark & Linda''s house"}'::jsonb, '[{"time":5,"item":"Opening prayer and year-in-review wins","owner":"m1"},{"time":10,"item":"Commitment check-in, round the table","owner":"all"},{"time":25,"item":"Hot seat: Ben","owner":"m7"},{"time":15,"item":"Lock in 2027 family goals","owner":"m2"},{"time":5,"item":"New commitments and close","owner":"m1"}]'::jsonb, 'm7', null, null, 'rule:2026-12'),
  ('f-2027-01', 'family', '2027-01-10T15:00:00-06:00', 60, 'January Shoreline', null, '[{"time":5,"item":"Opening prayer and wins of the month","owner":"m1"},{"time":10,"item":"Commitment check-in, round the table","owner":"all"},{"time":25,"item":"Hot seat: Grace","owner":"m8"},{"time":15,"item":"Choose the 2027 book list","owner":"m10"},{"time":5,"item":"New commitments and close","owner":"m1"}]'::jsonb, 'm8', null, null, 'rule:2027-01');
