insert into public.goals (id, group_id, member_id, period, title, why, target_date, status, accountability_ask) values
  ('g-m1-1', 'family', 'm1', 'Q4 2026', 'Finish the family trust update', 'So nobody has to guess what we wanted.', '2026-12-15', 'active', 'Ask me each month if the attorney has the latest draft.'),
  ('g-m1-2', 'family', 'm1', 'Q4 2026', 'Hand off the investment fund books to Tom', 'Two people should know how it works, not one.', '2026-12-31', 'active', ''),
  ('g-m2-1', 'family', 'm2', 'Q4 2026', 'Run the Thanksgiving give-back with 25 volunteers', 'Last year we had 11. I want the grandkids involved.', '2026-11-26', 'active', 'Hold me to sending the reminder emails on time.'),
  ('g-m2-2', 'family', 'm2', '2027', 'Lead the 2027 family goals session', 'We keep saying we''ll write them down.', '2027-01-10', 'active', ''),
  ('g-m3-1', 'family', 'm3', 'Q4 2026', 'Prove the food truck idea with real sales', 'I want numbers, not a hunch, before I sign a lease.', '2026-12-31', 'active', 'Ask me every meeting for my sales-per-hour number.'),
  ('g-m3-2', 'family', 'm3', '2027', 'Save $20k for the truck down payment', 'No loan for the build-out.', '2027-06-30', 'active', ''),
  ('g-m4-1', 'family', 'm4', 'Q4 2026', 'Grow the bookkeeping business to $2,500/month', 'Enough to drop my Saturday job.', '2026-12-31', 'active', 'Ask me how many new clients I talked to this month.'),
  ('g-m4-2', 'family', 'm4', 'Q4 2026', 'Take on two new clients', 'Price increase only works if new clients say yes too.', '2026-12-31', 'active', ''),
  ('g-m5-1', 'family', 'm5', 'Q4 2026', 'Decide on the Maple duplex', 'It''s been sitting for a year. Fix it or sell it.', '2026-12-13', 'active', 'Don''t let me push the decision past December.'),
  ('g-m5-2', 'family', 'm5', '2027', 'Get the second lot surveyed', 'Needed before any building plans.', '2027-03-31', 'paused', ''),
  ('g-m6-1', 'family', 'm6', '2027', 'Land a product manager role', 'I''ve been an analyst for six years. Time to move.', '2027-03-31', 'active', 'Ask me how many coffee chats I had this month.'),
  ('g-m6-2', 'family', 'm6', 'Q4 2026', 'Finish the product management certificate', 'Gives me something concrete on the resume.', '2026-12-20', 'active', ''),
  ('g-m7-1', 'family', 'm7', 'Q4 2026', 'Read four business books this year', 'I want to learn before I start something.', '2026-12-31', 'active', 'Ask me which chapter I''m on.'),
  ('g-m7-2', 'family', 'm7', '2027', 'Price out a lawn care side business', 'Spring is when it would start.', '2027-02-28', 'active', ''),
  ('g-m8-1', 'family', 'm8', 'Q4 2026', 'Build a $1,000 emergency fund', 'So one car repair doesn''t wreck the semester.', '2026-12-31', 'active', 'Ask me my balance each meeting.'),
  ('g-m8-2', 'family', 'm8', 'Q4 2026', 'Start investing every month', 'Grandpa says the earlier the better.', '2026-11-01', 'done', ''),
  ('g-m9-1', 'family', 'm9', 'Q4 2026', 'Publish clear quarterly reports for the family fund', 'Everyone should understand where the money is.', '2026-12-31', 'active', 'Ask me if the Q4 report went out by January 15.'),
  ('g-m9-2', 'family', 'm9', 'Q4 2026', 'Learn the fund books from Mark', 'So it doesn''t all sit with one person.', '2026-12-31', 'active', ''),
  ('g-m10-1', 'family', 'm10', 'Q4 2026', 'Get every family member to one service day', 'Giving back together is the point.', '2026-11-21', 'active', 'Ask me if the food bank shift is booked.'),
  ('g-m10-2', 'family', 'm10', '2027', 'Pick a 2027 book list everyone will read', 'Last year''s list was too long.', '2027-01-10', 'active', '');
