  ('c-f10-m2', 'family', 'm2', 'f-2026-10', 'Finish the Thanksgiving give-back sign-up sheet and send it to the church office.', 'done', 'Sent. 14 volunteers so far.', 'g-m2-1', '2026-10-19T18:40:00-05:00', '2026-10-19T18:40:00-05:00', '2026-10-19T18:40:00-05:00'),
  ('c-f10-m3', 'family', 'm3', 'f-2026-10', 'Run three Saturday pop-ups and track sales per hour.', 'in_progress', 'Two done: $412 and $538. Last one is Nov 1.', 'g-m3-1', null, '2026-10-26T20:05:00-05:00', '2026-10-26T20:05:00-05:00'),
  ('c-f10-m4', 'family', 'm4', 'f-2026-10', 'Email all current clients the new January pricing.', 'done', 'All 6 replied. Nobody left.', 'g-m4-1', '2026-10-15T09:30:00-05:00', '2026-10-15T09:30:00-05:00', '2026-10-15T09:30:00-05:00'),
  ('c-f10-m5', 'family', 'm5', 'f-2026-10', 'Get two contractor bids on the Maple duplex repairs.', 'in_progress', 'One bid in at $16,400. Waiting on the second.', 'g-m5-1', null, '2026-10-22T12:00:00-05:00', '2026-10-22T12:00:00-05:00'),
  ('c-f10-m6', 'family', 'm6', 'f-2026-10', 'Update my resume and have coffee with two people in product management.', 'in_progress', 'Resume done. Coffee booked for Nov 3.', 'g-m6-1', null, '2026-10-20T07:50:00-05:00', '2026-10-20T07:50:00-05:00'),
  ('c-f10-m7', 'family', 'm7', 'f-2026-10', 'Read The E-Myth Revisited chapters 5-8 and bring one idea to apply.', 'not_started', '', 'g-m7-1', null, '2026-10-11T17:00:00-05:00', '2026-10-11T17:00:00-05:00'),
  ('c-f10-m8', 'family', 'm8', 'f-2026-10', 'Open a Roth IRA and set up a $100/month auto-deposit.', 'done', 'Opened with Fidelity. First deposit Nov 1.', 'g-m8-2', '2026-10-13T21:10:00-05:00', '2026-10-13T21:10:00-05:00', '2026-10-13T21:10:00-05:00'),
  ('c-f10-m9', 'family', 'm9', 'f-2026-10', 'Write up the Q3 family fund summary and share it before November.', 'done', 'Shared in the family email. Up 4.1% for Q3.', 'g-m9-1', '2026-10-28T08:20:00-05:00', '2026-10-28T08:20:00-05:00', '2026-10-28T08:20:00-05:00'),
  ('c-f10-m10', 'family', 'm10', 'f-2026-10', 'Book the food bank shift for the whole family on Nov 21.', 'not_started', '', 'g-m10-1', null, '2026-10-11T17:00:00-05:00', '2026-10-11T17:00:00-05:00');
insert into public.checkins (id, group_id, meeting_id, member_id, win, challenge, submitted_at, edited_at) values
  ('k-f-2026-10-m1', 'family', 'f-2026-10', 'm1', 'Picked our estate attorney and sent her everything.', 'Getting everyone''s schedules lined up for the trust meeting.', '2026-10-10T20:00:00-05:00', null),
  ('k-f-2026-10-m2', 'family', 'f-2026-10', 'm2', 'Church approved Nov 21 for the give-back.', 'Not enough volunteers under 30 yet.', '2026-10-09T18:30:00-05:00', null),
  ('k-f-2026-10-m3', 'family', 'f-2026-10', 'm3', 'Two pop-ups, $950 in sales.', 'Running out of food by 1pm both times.', '2026-10-10T22:10:00-05:00', null),
  ('k-f-2026-10-m4', 'family', 'f-2026-10', 'm4', 'Two new clients signed at $250.', 'Writing the price email to the old clients.', '2026-10-08T07:45:00-05:00', null),
  ('k-f-2026-10-m5', 'family', 'f-2026-10', 'm5', 'Realtor came back at $205k as-is.', 'Linda and I don''t agree yet on fix vs sell.', '2026-10-09T20:45:00-05:00', null),
  ('k-f-2026-10-m6', 'family', 'f-2026-10', 'm6', 'Finished half the PM course.', 'No time for coffee chats with the new project at work.', '2026-10-10T21:00:00-05:00', null),
  ('k-f-2026-10-m9', 'family', 'f-2026-10', 'm9', 'Q3 fund numbers closed, up 4.1%.', 'Explaining the bond fund drop simply.', '2026-10-11T09:30:00-05:00', null),
  ('k-f-2026-10-m10', 'family', 'f-2026-10', 'm10', 'Food bank said yes to the whole family on Nov 21.', 'Getting the cousins to commit.', '2026-10-11T14:50:00-05:00', null),
  ('k-f-2026-11-m2', 'family', 'f-2026-11', 'm2', '14 volunteers signed up, including three grandkids.', 'Finding a second van for the drive.', '2026-10-27T19:10:00-05:00', null),
  ('k-f-2026-11-m4', 'family', 'f-2026-11', 'm4', 'All six clients agreed to the January price.', 'Keeping up with month-end now that I''m busier.', '2026-10-28T08:05:00-05:00', null),
  ('k-f-2026-11-m9', 'family', 'f-2026-11', 'm9', 'Q3 report out and everyone opened it.', 'Tracking down the old brokerage statements.', '2026-10-29T07:30:00-05:00', null),
  ('k-f-2026-11-m10', 'family', 'f-2026-11', 'm10', 'Ordered matching volunteer t-shirts.', 'Still need to book the food bank shift online.', '2026-10-30T12:15:00-05:00', null);
insert into public.asks (id, group_id, member_id, title, detail, needs, status, created_at) values
  ('a-f1', 'family', 'm3', 'Anyone know a commercial kitchen I can rent by the hour?', 'The pop-ups are outgrowing Mom''s kitchen. Looking for something near Elm Grove under $25/hour.', 'hands', 'open', '2026-10-27T18:20:00-05:00'),
  ('a-f2', 'family', 'm6', 'Mock interview for a product manager role', 'I have a first-round interview on Nov 12. Would love 30 minutes with someone who''s hired people before.', null, 'open', '2026-10-29T21:00:00-05:00'),
  ('a-f3', 'family', 'm10', 'Need a second van for Nov 21', 'We have 14 people going to the food bank and room for 8.', 'hands', 'open', '2026-10-24T10:30:00-05:00'),
  ('a-f4', 'family', 'm8', 'Which Roth IRA provider should I use?', 'Fidelity, Vanguard or Schwab? I want low fees and an app that''s easy.', 'deciding', 'resolved', '2026-10-05T16:00:00-05:00');
insert into public.ask_replies (id, ask_id, group_id, member_id, text, can_help, created_at) values
  ('a-f1-r1', 'a-f1', 'family', 'm2', 'The church kitchen sits empty on weekdays. I''ll ask Pastor Dave.', true, '2026-10-27T19:05:00-05:00'),
  ('a-f1-r2', 'a-f1', 'family', 'm9', 'Try the culinary school on 4th. They rented to a caterer we know.', false, '2026-10-28T08:40:00-05:00'),
  ('a-f3-r1', 'a-f3', 'family', 'm5', 'Our minivan seats 7. It''s yours that day.', true, '2026-10-24T12:00:00-05:00'),
  ('a-f4-r1', 'a-f4', 'family', 'm9', 'Any of the three is fine. Fidelity has no minimum and a good app.', true, '2026-10-05T18:30:00-05:00'),
  ('a-f4-r2', 'a-f4', 'family', 'm1', 'Pick a target-date fund and leave it alone.', false, '2026-10-06T07:15:00-05:00');
insert into public.announcements (id, group_id, author_id, title, body, pinned, created_at, updated_at) values
  ('an-f1', 'family', 'm1', 'November meeting moves to the Whitakers''', 'Our kitchen is getting new floors that week, so Hannah and Tom are hosting Nov 8. Same time, 3:00. Bring a chair if you have a folding one. Linda is doing chili, so sides and desserts are welcome.', true, '2026-10-29T09:15:00-05:00', '2026-10-29T09:15:00-05:00'),
  ('an-f2', 'family', 'm10', 'Food bank shift is confirmed for Nov 21', 'We have the 9:00 to 12:00 shift at Northside Food Bank for all of us. Closed-toe shoes, no jewelry. Kids 10 and up can work the sorting line. Lunch at Mom and Dad''s after.', false, '2026-10-27T19:30:00-05:00', '2026-10-27T19:30:00-05:00'),
  ('an-f3', 'family', 'm9', 'Q3 family fund summary is ready', 'The fund finished the quarter up 4.1%. I wrote a one-page summary with a plain-English note on why the bond fund dipped. Paper copies at the meeting, or ask me for the PDF.', false, '2026-10-24T14:00:00-05:00', '2026-10-24T14:00:00-05:00'),
  ('an-f4', 'family', 'm1', 'Welcome to the app', 'This is where we''ll keep the agenda, our commitments and the hot seat schedule from now on. Check in before each meeting and keep your commitment status current. Questions go to me or Emily.', false, '2026-10-05T18:00:00-05:00', '2026-10-05T18:00:00-05:00');
insert into public.announcement_comments (id, announcement_id, group_id, member_id, text, created_at) values
  ('an-f1-c1', 'an-f1', 'family', 'm10', 'We''re excited. Park on the street, the driveway will be full of the van.', '2026-10-29T10:02:00-05:00'),
  ('an-f1-c2', 'an-f1', 'family', 'm3', 'I''ll bring cornbread from the pop-up batch.', '2026-10-29T12:40:00-05:00'),
  ('an-f1-c3', 'an-f1', 'family', 'm8', 'I can come straight from the clinic, might be 15 min late.', '2026-10-30T08:10:00-05:00'),
  ('an-f2-c1', 'an-f2', 'family', 'm2', 'Thank you for setting this up. This is my favorite day of the year.', '2026-10-27T20:05:00-05:00'),
  ('an-f2-c2', 'an-f2', 'family', 'm7', 'Can I bring my friend Marcus? He needs service hours.', '2026-10-28T16:22:00-05:00'),
  ('an-f2-c3', 'an-f2', 'family', 'm10', 'Yes! Just send me his full name for the sign-in list.', '2026-10-28T17:01:00-05:00'),
  ('an-f3-c1', 'an-f3', 'family', 'm1', 'Clear and short. This is exactly what we needed.', '2026-10-24T15:10:00-05:00'),
  ('an-f4-c1', 'an-f4', 'family', 'm6', 'Happy to help anyone get it on their phone.', '2026-10-05T19:12:00-05:00');
insert into public.ideas (id, group_id, member_id, type, title, note, url, created_at) values
  ('i-f1', 'family', 'm4', 'tool', 'Wave for simple invoicing', 'Free invoicing that a lot of my small clients use. Good for Jake once the truck takes catering orders.', 'https://www.waveapps.com', '2026-10-28T11:00:00-05:00'),
  ('i-f2', 'family', 'm6', 'podcast', 'How I Built This: the Chobani episode', 'A small-town factory bought with an SBA loan. Made me think of Daniel''s lot.', 'https://www.npr.org/podcasts/510313/how-i-built-this', '2026-10-25T21:00:00-05:00'),
  ('i-f3', 'family', 'm2', 'idea', 'Write our family mission in one sentence', 'Before we set 2027 goals, agree on one sentence about why this group exists. Then each goal should point at it.', '', '2026-10-22T08:30:00-05:00'),
  ('i-f4', 'family', 'm9', 'article', 'Roth IRA for students: the 5-minute version', 'Grace asked about this. Short, no sales pitch.', 'https://www.investor.gov/introduction-investing', '2026-10-20T19:45:00-05:00'),
  ('i-f5', 'family', 'm3', 'idea', 'Pre-orders by text for Saturday pop-ups', 'I keep running out by 1pm. Taking pre-orders on Friday night would tell me how much to cook.', '', '2026-10-18T22:10:00-05:00'),
  ('i-f6', 'family', 'm5', 'link', 'County permit lookup', 'You can see every permit pulled on a property. Useful before buying anything older.', 'https://www.example.gov/permits', '2026-10-12T17:00:00-05:00'),
  ('i-f7', 'family', 'm7', 'other', 'Lawn care price sheet from Tyler''s dad', 'He charges $45 a cut for a quarter acre and $120 for leaf cleanup. I''m going to start lower.', '', '2026-10-09T16:00:00-05:00');
