insert into public.books (id, group_id, title, author, suggested_by, why, group_book, created_at) values
  ('b-f1', 'family', 'The Psychology of Money', 'Morgan Housel', 'm9', 'Short chapters, no math. Best book I know for getting the whole family on the same page about money.', true, '2026-09-14T10:00:00-05:00'),
  ('b-f2', 'family', 'The E-Myth Revisited', 'Michael E. Gerber', 'm4', 'Every small business owner I work with should read it before they hire anyone.', false, '2026-08-10T12:00:00-05:00'),
  ('b-f3', 'family', 'Atomic Habits', 'James Clear', 'm2', 'Small habits are how we keep commitments between meetings.', false, '2026-07-01T09:00:00-05:00'),
  ('b-f4', 'family', 'Die With Zero', 'Bill Perkins', 'm1', 'Challenges how Linda and I think about giving while we''re alive. I''d like the kids'' take.', false, '2026-10-02T15:00:00-05:00'),
  ('b-f5', 'family', 'Inspired', 'Marty Cagan', 'm6', 'The book every product manager interview seems to assume you''ve read.', false, '2026-09-20T20:00:00-05:00'),
  ('b-f6', 'family', 'Kitchen Confidential', 'Anthony Bourdain', 'm3', 'What working a line is really like. Fun read even if you never cook.', false, '2026-10-19T23:00:00-05:00'),
  ('b-f7', 'family', 'The Richest Man in Babylon', 'George S. Clason', 'm2', 'Grandpa gave me this at 18. Old, short and still right.', false, '2026-06-15T10:00:00-05:00');
insert into public.book_comments (id, book_id, group_id, member_id, text, created_at) values
  ('b-f1-c1', 'b-f1', 'family', 'm8', 'Chapter on ''enough'' hit me hard.', '2026-10-15T21:00:00-05:00'),
  ('b-f1-c2', 'b-f1', 'family', 'm1', 'Read it twice. Let''s discuss chapter 6 in November.', '2026-10-20T07:40:00-05:00'),
  ('b-f2-c1', 'b-f2', 'family', 'm7', 'The part about working on vs in your business is my commitment this month.', '2026-10-12T19:00:00-05:00'),
  ('b-f4-c1', 'b-f4', 'family', 'm10', 'Controversial pick, Dad. I''m in.', '2026-10-02T18:00:00-05:00'),
  ('b-f7-c1', 'b-f7', 'family', 'm8', 'Finished it on the bus. Pay yourself first.', '2026-09-30T08:00:00-05:00');
