insert into public.group_settings (group_id, branding, verse, credit, rules, rules_version, location_default, meeting_rule, training_rule, agenda_template, notification_options) values
  ('entrepreneur', '{"nextLabel":"Next flight","enterLabel":"Board","colors":{"primary":"#152238","accent":"#C9973A","background":"#F4EFE3","text":"#152238","surface":"#FFFDF7","muted":"#4A5566","rule":"#E2DCCB","good":"#1F6E43","goodBg":"#DCEFE2"},"logoText":"FC","logoMask":"brand/flight-club-logo-mask-720.png"}'::jsonb, '{"short":"If I rise on the wings of the dawn…","full":"If I rise on the wings of the dawn, if I settle on the far side of the sea, even there your hand will guide me.","ref":"Psalm 139:9"}'::jsonb, '{"label":"Built by TPG","url":"https://PLACEHOLDER-tpg-website"}'::jsonb, '["Confidential means confidential. Names, numbers and stories stay in the room.","Attend every session. Miss two in a row and Rachel will call you.","Check in by the start of the meeting. Hot seat prep is due 24 hours before.","Start at 7:00 sharp and end on time.","Give experience, not opinions. Say what you did, not what someone should do.","Leave with one commitment you can finish before the next session."]'::jsonb, 1, '{"type":"inperson","label":"In person","url":null,"address":"Location shared in announcements"}'::jsonb, '{"nth":3,"weekday":5,"start":"07:00","durationMinutes":120,"titleTemplate":"{month} Flight Club"}'::jsonb, '{"nth":3,"weekday":3,"start":"12:00","durationMinutes":60,"titleTemplate":"{month} Training"}'::jsonb, '[{"time":10,"item":"Opening prayer and devotional","owner":"e1"},{"time":10,"item":"Quick wins, one sentence each","owner":"all"},{"time":25,"item":"Commitment check-in","owner":"all"},{"time":45,"item":"Hot seat: {hotSeatName}","owner":"{hotSeat}"},{"time":20,"item":"Teaching: setting the year before the Lord","owner":"all"},{"time":10,"item":"New commitments and closing prayer","owner":"all"}]'::jsonb, '{"oneHourReminder":false}'::jsonb);
