insert into public.members (id, group_id, name, role, bio, focus, can_help_with, working_genius, sort_order) values
  ('e1', 'entrepreneur', 'Rachel Kim', 'admin', 'CEO of Ledgerly, scheduling software for physical therapy clinics. 14 people.', 'Closing Hendricks and hiring a head of sales.', array['Enterprise sales','SaaS pricing','Fundraising decks']::text[], '{"geniuses":["I","G"],"competencies":["D","W"],"frustrations":["E","T"]}'::jsonb, 1),
  ('e2', 'entrepreneur', 'Marcus Bell', 'member', 'Owner of Bell Home Services, HVAC and plumbing in north Austin. 22 techs.', 'Hiring an ops manager so he can get out of dispatch.', array['Hiring field staff','Fleet and vehicles','Running a service business']::text[], '{"geniuses":["E","T"],"competencies":["G","D"],"frustrations":["W","I"]}'::jsonb, 2),
  ('e3', 'entrepreneur', 'Priya Natarajan', 'member', 'Founder of Stackwise, inventory software for craft breweries.', 'Signing the first two channel partners.', array['Partnership terms','Product roadmaps','Churn analysis']::text[], '{"geniuses":["W","D"],"competencies":["I","T"],"frustrations":["G","E"]}'::jsonb, 3),
  ('e4', 'entrepreneur', 'Luis Ortega', 'member', 'Owns Ortega Auto, a two-bay independent repair shop with a waiting list.', 'Deciding on a second location before spring.', array['SBA loans','Shop operations','Buying used equipment']::text[], '{"geniuses":["D","T"],"competencies":["E","G"],"frustrations":["W","I"]}'::jsonb, 4),
  ('e5', 'entrepreneur', 'Dana Whitfield', 'member', 'Runs Whitfield Creative, a six-person branding agency on retainers.', 'Raising retainers 15% without losing the two big clients.', array['Brand and messaging','Client proposals','Agency pricing']::text[], '{"geniuses":["D","E"],"competencies":["W","T"],"frustrations":["I","G"]}'::jsonb, 5),
  ('e6', 'entrepreneur', 'Chris Albrecht', 'member', 'COO of a 40-person digital marketing agency.', 'Getting net margin from 12% to 20%.', array['Cutting software costs','Financial dashboards','Process docs']::text[], null, 6),
  ('e7', 'entrepreneur', 'Tasha Monroe', 'member', 'Leadership coach for first-time managers. Solo, moving to group programs.', 'Publishing ten client case studies.', array['Hard conversations','Facilitating a team offsite','Video on a budget']::text[], '{"geniuses":["G","W"],"competencies":["I","E"],"frustrations":["D","T"]}'::jsonb, 7),
  ('e8', 'entrepreneur', 'Owen Park', 'member', 'Owner of Park Precision, a contract machining plant. 31 employees.', 'Two CEO days a month away from the floor.', array['Manufacturing and quoting','Hiring skilled trades','Equipment financing']::text[], null, 8);
insert into public.meetings (id, group_id, starts_at, duration_minutes, title, location, agenda, hot_seat_member_id, hot_seat_prep, action_plan, source_key) values
  ('e-2026-08', 'entrepreneur', '2026-08-21T07:00:00-05:00', 120, 'August Flight Club', null, '[{"time":10,"item":"Opening prayer and devotional","owner":"e1"},{"time":10,"item":"Quick wins, one sentence each","owner":"all"},{"time":25,"item":"Commitment check-in","owner":"all"},{"time":45,"item":"Hot seat: Marcus on hiring a first ops manager","owner":"e2"},{"time":20,"item":"Teaching: stewardship and the business owner","owner":"all"},{"time":10,"item":"New commitments and closing prayer","owner":"all"}]'::jsonb, 'e2', '{"problem":"Revenue is $1.2M and I''m still doing dispatch myself. Do I hire an ops manager at $70k or promote my lead tech?","context":"11 techs, 3 vans on call. I spend about 25 hours a week on dispatch and scheduling.","whatTried":"Wrote a job description. Talked to my lead tech, who''s interested but nervous.","winLooksLike":"A hire decision and a 90-day plan for handing off dispatch.","submittedAt":"2026-08-19T21:00:00-05:00"}'::jsonb, null, 'rule:2026-08'),
  ('e-2026-09', 'entrepreneur', '2026-09-18T07:00:00-05:00', 120, 'September Flight Club', null, '[{"time":10,"item":"Opening prayer and devotional","owner":"e1"},{"time":10,"item":"Quick wins, one sentence each","owner":"all"},{"time":25,"item":"Commitment check-in","owner":"all"},{"time":45,"item":"Hot seat: Priya on a channel partner offer","owner":"e3"},{"time":20,"item":"Book discussion: Business for the Glory of God","owner":"all"},{"time":10,"item":"New commitments and closing prayer","owner":"all"}]'::jsonb, 'e3', '{"problem":"A reseller wants exclusive rights in Texas for 40% margin. Is exclusivity worth it for a guaranteed 200 seats?","context":"200 seats is about $96k ARR. We have 3 Texas customers today, all inbound.","whatTried":"Had two calls with them and asked for references.","winLooksLike":"Terms I''d sign tomorrow, and the walk-away point.","submittedAt":"2026-09-16T18:30:00-05:00"}'::jsonb, '{"adviceTaken":["Don''t give exclusivity without a seat minimum","Counter at 30% and a 12-month term","Ask for a 90-day out clause"],"nextStep":"Send the reseller a counter: non-exclusive, 30% margin, 12-month term.","deadline":"2026-09-30","goalId":"g-e3-1","savedAt":"2026-09-18T08:45:00-05:00"}'::jsonb, 'rule:2026-09'),
  ('e-2026-10', 'entrepreneur', '2026-10-16T07:00:00-05:00', 120, 'October Flight Club', null, '[{"time":10,"item":"Opening prayer and devotional","owner":"e1"},{"time":10,"item":"Quick wins, one sentence each","owner":"all"},{"time":25,"item":"Commitment check-in","owner":"all"},{"time":45,"item":"Hot seat: Luis on a second location","owner":"e4"},{"time":20,"item":"Teaching: work as worship","owner":"all"},{"time":10,"item":"New commitments and closing prayer","owner":"all"}]'::jsonb, 'e4', '{"problem":"Location one is at 85% capacity. Do I open a second shop with an SBA loan or add a Saturday shift first?","context":"Auto repair, 6 bays. Wait time for appointments is up to 9 days. SBA quote is $420k at 10.5%.","whatTried":"Toured two buildings. Asked my techs who''d work Saturdays (4 of 7 said yes).","winLooksLike":"Know whether demand is real before signing a 10-year lease.","submittedAt":"2026-10-14T20:10:00-05:00"}'::jsonb, '{"adviceTaken":["Run Saturdays for four weeks before any lease","Track margin per shift, not just revenue","Talk to the SBA lender anyway so you know the terms","Raise the labor rate $10 first"],"nextStep":"Run Saturday shifts for four weeks and compare margin to weekdays.","deadline":"2026-11-13","goalId":"g-e4-1","savedAt":"2026-10-16T09:45:00-05:00"}'::jsonb, 'rule:2026-10'),
  ('e-2026-11', 'entrepreneur', '2026-11-20T07:00:00-06:00', 120, 'November Flight Club', null, '[{"time":10,"item":"Opening prayer and devotional","owner":"e1"},{"time":10,"item":"Quick wins, one sentence each","owner":"all"},{"time":25,"item":"Commitment check-in","owner":"all"},{"time":45,"item":"Hot seat: Dana on raising prices","owner":"e5"},{"time":20,"item":"Teaching: generosity in pricing and pay","owner":"all"},{"time":10,"item":"New commitments and closing prayer","owner":"all"}]'::jsonb, 'e5', '{"problem":"My agency retainers haven''t gone up in 3 years. How do I raise them 15% without losing my two biggest clients?","context":"Those two clients are 48% of revenue and both run 40% over scope. Costs are up about 20% since 2023.","whatTried":"Pulled 12 months of hours vs retainer. Drafted an email but haven''t sent it.","winLooksLike":"A pricing plan and the exact words for the conversation with each client.","submittedAt":"2026-10-30T16:40:00-05:00"}'::jsonb, null, 'rule:2026-11'),
  ('e-2026-12', 'entrepreneur', '2026-12-18T07:00:00-06:00', 120, 'December Flight Club', null, '[{"time":10,"item":"Opening prayer and devotional","owner":"e1"},{"time":10,"item":"Quick wins, one sentence each","owner":"all"},{"time":25,"item":"Commitment check-in","owner":"all"},{"time":45,"item":"Hot seat: Chris","owner":"e6"},{"time":20,"item":"2027 one-page plans: swap with a partner","owner":"all"},{"time":10,"item":"New commitments and closing prayer","owner":"all"}]'::jsonb, 'e6', null, null, 'rule:2026-12'),
  ('e-2027-01', 'entrepreneur', '2027-01-15T07:00:00-06:00', 120, 'January Flight Club', null, '[{"time":10,"item":"Opening prayer and devotional","owner":"e1"},{"time":10,"item":"Quick wins, one sentence each","owner":"all"},{"time":25,"item":"Commitment check-in","owner":"all"},{"time":45,"item":"Hot seat: Tasha","owner":"e7"},{"time":20,"item":"Teaching: setting the year before the Lord","owner":"all"},{"time":10,"item":"New commitments and closing prayer","owner":"all"}]'::jsonb, 'e7', null, null, 'rule:2027-01');
