insert into public.goals (id, group_id, member_id, period, title, why, target_date, status, accountability_ask) values
  ('g-e1-1', 'entrepreneur', 'e1', 'Q4 2026', 'Hit $1.5M ARR by year end', 'It''s the number that gets us to break-even.', '2026-12-31', 'active', 'Ask me for the ARR number every month, no rounding up.'),
  ('g-e1-2', 'entrepreneur', 'e1', '2027', 'Hire a head of sales', 'I can''t be the only closer in 2027.', '2027-03-31', 'active', ''),
  ('g-e2-1', 'entrepreneur', 'e2', 'Q4 2026', 'Get out of dispatch', 'I should be selling, not scheduling.', '2026-12-31', 'active', 'Ask me how many hours I spent on dispatch last week.'),
  ('g-e2-2', 'entrepreneur', 'e2', '2027', 'Open a second service area in Round Rock', 'Half our calls come from there already.', '2027-06-30', 'active', ''),
  ('g-e3-1', 'entrepreneur', 'e3', 'Q4 2026', 'Sign two channel partners', 'Partners scale faster than my one sales rep.', '2026-12-31', 'active', 'Hold me to two signed contracts, not two good calls.'),
  ('g-e3-2', 'entrepreneur', 'e3', '2027', 'Cut churn under 2% monthly', 'Growth means nothing if they leave.', '2027-03-31', 'active', ''),
  ('g-e4-1', 'entrepreneur', 'e4', 'Q4 2026', 'Decide on a second location', 'Waiting lists are lost customers.', '2026-12-31', 'active', 'Ask me for the Saturday margin numbers.'),
  ('g-e4-2', 'entrepreneur', 'e4', 'Q4 2026', 'Raise the labor rate to $145/hour', 'We''re $20 under the dealer.', '2026-11-30', 'active', ''),
  ('g-e5-1', 'entrepreneur', 'e5', 'Q4 2026', 'Raise retainers 15% across the board', 'Costs went up and I didn''t.', '2027-01-31', 'active', 'Ask me if I''ve had the conversation with both big clients.'),
  ('g-e5-2', 'entrepreneur', 'e5', '2027', 'No client over 25% of revenue', 'Two clients is too much risk.', '2027-12-31', 'active', ''),
  ('g-e6-1', 'entrepreneur', 'e6', 'Q4 2026', 'Get to 20% net margin', 'We grew revenue but not profit.', '2026-12-31', 'active', 'Ask me what I cut this month.'),
  ('g-e6-2', 'entrepreneur', 'e6', 'Q4 2026', 'Write a one-page 2027 plan', 'So the team knows what matters.', '2026-12-03', 'active', ''),
  ('g-e7-1', 'entrepreneur', 'e7', 'Q4 2026', 'Build a library of 10 client case studies', 'Referrals ask for proof.', '2026-12-31', 'active', 'Ask me how many are published, not filmed.'),
  ('g-e7-2', 'entrepreneur', 'e7', '2027', 'Launch a group coaching offer', 'One-to-one doesn''t scale.', '2027-04-30', 'paused', ''),
  ('g-e8-1', 'entrepreneur', 'e8', 'Q4 2026', 'Work on the business two days a month', 'I''m stuck in the plant every day.', '2026-12-31', 'active', 'Ask me if the CEO days actually happened.'),
  ('g-e8-2', 'entrepreneur', 'e8', 'Q4 2026', 'Finish the 2027 hiring plan', 'We need 6 people and no plan.', '2026-11-15', 'done', '');
