  ('k-e-2026-10-e8', 'entrepreneur', 'e-2026-10', 'e8', 'Two real CEO days. Wrote the hiring plan.', 'Plant manager quit.', '2026-10-15T20:20:00-05:00', null),
  ('k-e-2026-11-e3', 'entrepreneur', 'e-2026-11', 'e3', 'Reseller accepted 32%, contract out.', 'Onboarding their team without a partner manager.', '2026-10-29T12:00:00-05:00', null),
  ('k-e-2026-11-e5', 'entrepreneur', 'e-2026-11', 'e5', 'Have the hours data for every client.', 'Nervous about the price conversation.', '2026-10-30T16:45:00-05:00', null),
  ('k-e-2026-11-e8', 'entrepreneur', 'e-2026-11', 'e8', 'Hired a new plant manager.', 'Getting him up to speed while I''m out two days.', '2026-10-30T07:00:00-05:00', null);
insert into public.asks (id, group_id, member_id, title, detail, needs, status, created_at) values
  ('a-e1', 'entrepreneur', 'e5', 'Script for a retainer price increase', 'If you''ve raised prices on a long-time client, what did you actually say? Looking for real wording.', 'deciding', 'open', '2026-10-30T17:00:00-05:00'),
  ('a-e2', 'entrepreneur', 'e2', 'Intro to a good fractional HR person', 'Hiring our first manager. Need help with comp bands and an offer letter.', 'hands', 'open', '2026-10-28T09:15:00-05:00'),
  ('a-e3', 'entrepreneur', 'e7', 'Video editor for short case studies', 'Two filmed, need someone who can turn around 90-second edits in a week. Budget around $300 each.', 'hands', 'open', '2026-10-25T13:30:00-05:00'),
  ('a-e4', 'entrepreneur', 'e4', 'SBA lender recommendations', 'Want a second quote before I commit to anything.', 'exploring', 'resolved', '2026-10-05T10:00:00-05:00');
insert into public.ask_replies (id, ask_id, group_id, member_id, text, can_help, created_at) values
  ('a-e1-r1', 'a-e1', 'entrepreneur', 'e1', 'I led with the hours data and offered a reduced scope option. Happy to share my email.', true, '2026-10-30T18:20:00-05:00'),
  ('a-e3-r1', 'a-e3', 'entrepreneur', 'e3', 'Our editor has room. I''ll send you her portfolio.', true, '2026-10-25T15:00:00-05:00'),
  ('a-e3-r2', 'a-e3', 'entrepreneur', 'e6', 'Check that she can deliver captions too.', false, '2026-10-26T08:10:00-05:00'),
  ('a-e4-r1', 'a-e4', 'entrepreneur', 'e8', 'Live Oak did our equipment loan. Fast and fair.', true, '2026-10-05T12:30:00-05:00');
insert into public.announcements (id, group_id, author_id, title, body, pinned, created_at, updated_at) values
  ('an-e1', 'entrepreneur', 'e1', 'November: Dana on the hot seat, prep is in', 'Dana''s question is about raising retainers 15% with two clients at 48% of revenue. Read her prep before Friday so we can skip the background and get to advice. 7:00 sharp at Common Desk, room B.', true, '2026-10-30T08:00:00-05:00', '2026-10-30T08:00:00-05:00'),
  ('an-e2', 'entrepreneur', 'e1', 'December session is our annual planning meeting', 'Dec 18 is our planning session. Bring a one-page 2027 plan: three goals, the one number you''ll watch, and the hire you need most. Chris will share his template.', false, '2026-10-28T12:00:00-05:00', '2026-10-28T12:00:00-05:00'),
  ('an-e3', 'entrepreneur', 'e3', 'Brewers Guild conference passes', 'I have two extra expo passes for Nov 18 in Dallas. Good for anyone selling to hospitality or food. Free to the group.', false, '2026-10-26T17:40:00-05:00', '2026-10-26T17:40:00-05:00');
insert into public.announcement_comments (id, announcement_id, group_id, member_id, text, created_at) values
  ('an-e1-c1', 'an-e1', 'entrepreneur', 'e4', 'Read it. I''ve got a story about our fleet client for you, Dana.', '2026-10-30T09:12:00-05:00'),
  ('an-e1-c2', 'an-e1', 'entrepreneur', 'e5', 'Thank you all. Bring the hard questions.', '2026-10-30T10:40:00-05:00'),
  ('an-e2-c1', 'an-e2', 'entrepreneur', 'e6', 'Template is posted in Ideas.', '2026-10-28T13:30:00-05:00'),
  ('an-e2-c2', 'an-e2', 'entrepreneur', 'e8', 'Can we start at 6:45 to get the extra time?', '2026-10-29T06:50:00-05:00'),
  ('an-e2-c3', 'an-e2', 'entrepreneur', 'e1', 'Yes, 6:45 start. Coffee will be ready.', '2026-10-29T08:05:00-05:00'),
  ('an-e3-c1', 'an-e3', 'entrepreneur', 'e2', 'I''ll take one. Restaurants are half our commercial calls.', '2026-10-26T18:05:00-05:00');
insert into public.ideas (id, group_id, member_id, type, title, note, url, created_at) values
  ('i-e1', 'entrepreneur', 'e6', 'tool', 'One-page 2027 plan template', 'Three goals, one number, one hire, three risks. Make a copy and fill it in before Dec 18.', 'https://docs.google.com/document/u/0/', '2026-10-28T13:25:00-05:00'),
  ('i-e2', 'entrepreneur', 'e5', 'article', 'Price increase letters that kept clients', 'Real examples, including what to say when the client pushes back.', 'https://hbr.org/topic/subject/pricing', '2026-10-27T20:00:00-05:00'),
  ('i-e3', 'entrepreneur', 'e2', 'idea', 'Pay techs a bonus for reviews that name them', 'We started $10 per 5-star review that mentions the tech by name. Reviews went from 6 to 31 a month.', '', '2026-10-25T19:10:00-05:00'),
  ('i-e4', 'entrepreneur', 'e7', 'podcast', 'Acquired: the Costco episode', 'Long, but the part on membership pricing is worth the drive.', 'https://www.acquired.fm', '2026-10-22T06:30:00-05:00'),
  ('i-e5', 'entrepreneur', 'e3', 'tool', 'ChurnZero alternative: a simple health score sheet', 'Logins, tickets and invoice status in one sheet. Flags at-risk accounts every Monday.', '', '2026-10-20T15:00:00-05:00'),
  ('i-e6', 'entrepreneur', 'e8', 'link', 'Texas Workforce skills grants', 'They paid for half our CNC training last year. Applications open in January.', 'https://www.twc.texas.gov', '2026-10-18T12:00:00-05:00'),
  ('i-e7', 'entrepreneur', 'e4', 'other', 'Saturday shifts: early numbers', 'Three Saturdays in. Margin is 6 points higher than weekdays because there''s no walk-in diagnostic work.', '', '2026-10-28T16:00:00-05:00');
