insert into public.books (id, group_id, title, author, suggested_by, why, group_book, created_at) values
  ('b-e1', 'entrepreneur', 'Never Split the Difference', 'Chris Voss', 'e5', 'I need it for my retainer conversations. Tactical empathy is exactly the skill I''m missing.', true, '2026-10-16T19:00:00-05:00'),
  ('b-e2', 'entrepreneur', 'Traction', 'Gino Wickman', 'e8', 'EOS gave our plant a weekly meeting that actually works.', false, '2026-08-22T08:00:00-05:00'),
  ('b-e3', 'entrepreneur', 'Who: The A Method for Hiring', 'Geoff Smart and Randy Street', 'e2', 'I''m about to hire an ops manager and can''t afford to get it wrong.', false, '2026-10-18T21:00:00-05:00'),
  ('b-e4', 'entrepreneur', 'The Six Types of Working Genius', 'Patrick Lencioni', 'e7', 'Explains why some of us love starting and hate finishing. Take the assessment first.', false, '2026-09-20T07:00:00-05:00'),
  ('b-e5', 'entrepreneur', 'Profit First', 'Mike Michalowicz', 'e6', 'Simple cash system. How we got from 4% to 12% margin.', false, '2026-07-30T12:00:00-05:00'),
  ('b-e6', 'entrepreneur', 'Buy Back Your Time', 'Dan Martell', 'e8', 'The audit exercise showed me I spend 9 hours a week on things a $25/hr person could do.', false, '2026-10-25T06:00:00-05:00'),
  ('b-e7', 'entrepreneur', 'The Mom Test', 'Rob Fitzpatrick', 'e3', 'Short. How to ask customers questions they can''t lie to you about.', false, '2026-06-25T09:00:00-05:00');
